function hgST(s){s=String(s==null?'':s);return s.replace(/\/+$/,'')}
function hgNL(){return String.fromCharCode(10)}
function hgQ(c){return String.fromCharCode(34)+c+String.fromCharCode(34)}
function hgDef(){return 'https://l205.arj2ftl0.cc'}
function hgPub(){return 'https://huangguoai.pages.dev/publish.js'}
function hgSubs(){return ['thu','pku','fdu','sjtu','zju','nju','xmu','sysu','whu','jlu','scu','ruc','bnu','nku','tju','sdu','hust','xjtu','hit']}
function hgRoots(){return ['arj2ftl0.cc','40ygo615.cc','h2na6qa39.cc']}
function hgHost(u){var s=hgST(u).replace(/^https?:\/\//,'');var i=s.indexOf('/');return i>0?s.substring(0,i):s}
function hgShort(h){h=String(h||'');var d=h.split('.');var t=d[0]||h;if(t.length>13)t=t.substring(0,13);return t}
function hgGV(k,d){var v='';try{v=String(source.get(k)||'')}catch(e){}
  if(!v||v=='null'||v=='undefined')v=d;return v?hgST(v):''}
function hgSV(k,v){try{source.put(k,String(v))}catch(e){}}
function hgT(t){try{java.longToast(t)}catch(e){try{java.toast(t)}catch(e2){}}}
function hgSites(){var r=hgGV('hg_sites','');var a=[];if(r){try{a=JSON.parse(r)}catch(e){}}return a}
function hgCand(){
  var p=hgGV('pub',hgPub());
  var h='';
  try{h=String(java.ajax(p))}catch(e){}
  if(h.length<500){try{h=String(java.ajax(hgPub()))}catch(e2){}}
  var roots=[];
  if(h.length>=500){
    var m=h.match(/var\s+urls\s*=\s*\[([\s\S]*?)\]/);
    if(m){var re=/['"]([a-z0-9.\-]+\.[a-z]{2,}\/?)['"]/gi,mm;
      while((mm=re.exec(m[1]))!=null)roots.push(mm[1].replace(/\/+$/,''))}
  }
  if(!roots.length)roots=hgRoots();
  var cs=[];
  for(var i=0;i<roots.length;i++)for(var j=0;j<hgSubs().length;j++)cs.push('https://'+hgSubs()[j]+'.'+roots[i]);
  for(var k=0;k<hgRoots().length;k++)cs.push('https://'+hgRoots()[k]);
  cs.push(hgDef());
  var seen={},ls=[];
  for(var m2=0;m2<cs.length;m2++){if(!seen[cs[m2]]){seen[cs[m2]]=1;ls.push(cs[m2])}}
  return ls}
function hgProbe(u){
  var t0=Date.now();
  try{
    var r=java.ajax(u+'/');
    var b=String(r);
    if(b.length>20000)return {ok:true,ms:Date.now()-t0};
  }catch(e){}
  return {ok:false,ms:-1}}
function FQ_siteName(i){
  try{
    var a=hgSites();
    if(!a.length)return '线路'+(i+1);
    if(i>=a.length)return '';
    var s=a[i];
    var cur=hgGV('hg_line',hgDef());
    return hgShort(s.host)+' '+s.ms+'ms'+(s.url===cur?' ✓':'');
  }catch(e){return '线路'+(i+1)}
}
function FQ_hgGo(){
  try{
    var p=hgGV('pub',hgPub());
    if(!p||p.indexOf('http')!=0){hgT('发布页地址无效：需以 http:// 或 https:// 开头');return}
    hgT('正在抓取发布页并测速...');
    var ls=hgCand();
    var urls=[];
    for(var i=0;i<ls.length;i++)urls.push(ls[i]+'/');
    var rows=[];
    var res=null;
    try{res=java.ajaxAll(urls)}catch(e){}
    if(res&&res.length){
      for(var j=0;j<res.length&&j<ls.length;j++){
        var r=res[j];
        var code=0,ct=-1,bl=0;
        try{code=r.raw.code()}catch(e){}
        try{ct=r.callTime()}catch(e2){}
        try{bl=String(r.body()).length}catch(e3){}
        if(code>=200&&code<400&&bl>20000)rows.push({url:ls[j],host:hgHost(ls[j]),ms:ct});
      }
    }else{
      for(var j2=0;j2<ls.length;j2++){
        var p2=hgProbe(ls[j2]);
        if(p2.ok)rows.push({url:ls[j2],host:hgHost(ls[j2]),ms:p2.ms});
      }
    }
    if(!rows.length){hgT('测速完成：'+ls.length+' 条线路全部不可用');return}
    rows.sort(function(x,y){return x.ms-y.ms});
    rows=rows.slice(0,12);
    hgSV('hg_sites',JSON.stringify(rows));
    hgSV('hg_line',rows[0].url);
    hgSV('hg_line_ts',String(Date.now()));
    hgT('测速完成（'+ls.length+' 条，可用 '+rows.length+' 条）'+hgNL()+'已选最快：'+rows[0].host+'（'+rows[0].ms+'ms）'+hgNL()+'若按钮名未刷新，重新打开本面板即可');
    try{java.reLoginView(false)}catch(e){}
  }catch(e){hgT('测速失败：'+String(e).substring(0,100))}
}
function FQ_hgPick(i){
  try{
    var a=hgSites();
    if(!a.length||!a[i]){
      hgT('该线路尚未测速，请先点「获取网址并测速」');
      return;
    }
    hgSV('hg_line',a[i].url);
    hgSV('hg_line_ts',String(Date.now()));
    hgT('已选择网站：'+a[i].host+hgNL()+'延迟：'+a[i].ms+'ms');
    try{java.reLoginView(false)}catch(e){}
  }catch(e){hgT('切换失败：'+String(e).substring(0,80))}
}
function FQ_hgCur(){
  try{hgT('当前线路：'+hgGV('hg_line',hgDef()))}catch(e){}
}
function FQ_hgChk(){
  try{
    var L=hgGV('hg_line',hgDef());
    var h='';
    try{h=String(java.ajax(L+'/profile/'))}catch(e){}
    if(h.length<2000){hgT('无法连接线路：'+L+hgNL()+'请检查网络或切换线路');return}
    var guest=h.indexOf('data-auth-open='+hgQ('login')+'>'+String.fromCharCode(30331,24405,47,27880,20876))>=0;
    var dash=h.indexOf('ID'+String.fromCharCode(65306)+String.fromCharCode(8212))>=0;
    var out=h.indexOf(String.fromCharCode(36864,20986))>=0||h.indexOf('signOut')>=0||h.indexOf('logout')>=0;
    if(guest&&dash)hgT('游客状态（未登录）'+hgNL()+'搜索/详情/目录/播放均可正常使用'+hgNL()+'登录后可看收藏与观看历史'+hgNL()+'当前线路：'+L);
    else if(out)hgT('已登录'+hgNL()+'当前线路：'+L);
    else hgT('状态未知（页面结构可能已变化）'+hgNL()+'当前线路：'+L);
  }catch(e){hgT('检查失败：'+String(e).substring(0,80))}
}
function FQ_hgRst(){
  try{
    hgSV('pub',hgPub());hgSV('hg_line',hgDef());hgSV('hg_line_ts','0');hgSV('hg_sites','');
    hgT('已恢复默认'+hgNL()+'线路：'+hgDef());
    try{java.reLoginView(false)}catch(e){}
  }catch(e){}
}
