if(!root||root.indexOf('http')!==0){try{root=String(source.getBookSourceUrl())}catch(e2){root=''}}
root=root.split(String.fromCharCode(35,35))[0];
if(!root||root.indexOf('http')!==0)root=String(baseUrl||'').split(String.fromCharCode(35,35))[0].replace(/\/$/,'');
root=root.replace(/\/$/,'');
var list=[];
var m=h.match(/data-track-total-episode="(\d+)"/);
if(m){
  var total=parseInt(m[1]);
  var vr=String(baseUrl).replace(/\/$/,'').replace(/\/ep-\d+$/,'');
  for(var i=1;i<=total;i++){list.push('第'+i+'集'+String.fromCharCode(9)+vr+(i===1?'/':'/ep-'+i+'/'));}
  return list;
}
var li=h.indexOf('hg-list-page');
var body=(li>=0)?h.substring(li):h;
var re=/data-track-title="([^"]*)"/g,mm;
while((mm=re.exec(body))!=null){
  var st=body.lastIndexOf('<div',mm.index);
  var seg=body.substring(st,st+1500);
  var u=seg.match(/href="(\/video\/\d+\/)"/);
  if(!u)continue;
  list.push(mm[1]+String.fromCharCode(9)+root+u[1]);
}
if(!list.length)list.push('专题视频'+String.fromCharCode(9)+root+'/');
return list;
})()

